#include <vector>
#include <list>
#include <set>

int main() {
    std::list<double> source = {1.1, 2.2, 3.3};

    // Initializing a vector<int> from a list<double>.
    // Source type (double) is convertible to destination type (int).
    std::vector<int> target_vec(source.begin(), source.end());
    // target_vec contains {1, 2, 3}

    // Initializing a set<int> from the vector range
    std::set<int> target_set(target_vec.begin(), target_vec.end());
}
